<?php
require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';oecrm_require_admin_login();$companyId=oecrm_current_company_id($conn);$id=(int)($_GET['id']??0);$r=mysqli_fetch_assoc(mysqli_query($conn,'SELECT f.*,c.display_name,c.legal_name,c.billing_address,c.tax_id,c.email client_email,co.display_name company_name,co.address company_address,co.gstin FROM finance_invoices f JOIN clients c ON c.id=f.client_id JOIN companies co ON co.id=f.company_id WHERE f.id='.$id.' AND f.company_id='.$companyId));if(!$r)exit('Invoice not found.');$items=mysqli_query($conn,'SELECT * FROM finance_invoice_items WHERE invoice_id='.$id);if(!$r['viewed_at'])mysqli_query($conn,'UPDATE finance_invoices SET viewed_at=NOW(),status=IF(status="sent","viewed",status) WHERE id='.$id);
?><!doctype html><html><head><meta charset="utf-8"><title><?php echo oecrm_h($r['invoice_number']);?></title><style>body{font-family:Arial;color:#303448;margin:35px}.invoice{max-width:900px;margin:auto}.head{display:flex;justify-content:space-between;border-bottom:2px solid #666cff;padding-bottom:20px}.right{text-align:right}table{width:100%;border-collapse:collapse;margin-top:28px}th,td{padding:11px;border-bottom:1px solid #ddd;text-align:left}.totals{margin-left:auto;width:320px}.totals td:last-child{text-align:right}button{padding:10px 16px;background:#666cff;color:#fff;border:0}@media print{button{display:none}}</style></head><body><div class="invoice"><button onclick="window.print()">Download / Print PDF</button><div class="head"><div><h1>INVOICE</h1><strong><?php echo oecrm_h($r['company_name']);?></strong><p><?php echo nl2br(oecrm_h($r['company_address']));?><br>GSTIN: <?php echo oecrm_h($r['gstin']);?></p></div><div class="right"><h3><?php echo oecrm_h($r['invoice_number']);?></h3><p>Date: <?php echo date('d M Y',strtotime($r['invoice_date']));?><br>Due: <?php echo date('d M Y',strtotime($r['due_date']));?><br>Status: <?php echo ucwords(str_replace('_',' ',$r['status']));?></p></div></div><h3>Bill To</h3><p><strong><?php echo oecrm_h($r['legal_name']);?></strong><br><?php echo nl2br(oecrm_h($r['billing_address']));?><br><?php echo oecrm_h($r['client_email']);?><br>Tax ID: <?php echo oecrm_h($r['tax_id']);?></p><table><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Tax %</th><th>Amount</th></tr></thead><tbody><?php if(mysqli_num_rows($items)===0):?><tr><td>Professional services</td><td>1</td><td><?php echo number_format($r['subtotal'],2);?></td><td>-</td><td><?php echo number_format($r['subtotal'],2);?></td></tr><?php endif;?><?php while($i=mysqli_fetch_assoc($items)):?><tr><td><?php echo oecrm_h($i['description']);?></td><td><?php echo $i['quantity'];?></td><td><?php echo number_format($i['rate'],2);?></td><td><?php echo $i['tax_percent'];?></td><td><?php echo number_format($i['amount'],2);?></td></tr><?php endwhile;?></tbody></table><table class="totals"><tr><td>Subtotal</td><td><?php echo number_format($r['subtotal'],2);?></td></tr><tr><td>Tax</td><td><?php echo number_format($r['tax_amount'],2);?></td></tr><tr><th>Total <?php echo $r['currency_code'];?></th><th><?php echo number_format($r['total_amount'],2);?></th></tr><tr><td>Paid</td><td><?php echo number_format($r['paid_amount'],2);?></td></tr><tr><th>Outstanding</th><th><?php echo number_format($r['total_amount']-$r['paid_amount'],2);?></th></tr></table></div></body></html>
